From d43f0e7f5a8c3f3d26de7032fc74ea92d8fa0e34 Mon Sep 17 00:00:00 2001
From: Christopher Faulet <cfaulet@haproxy.com>
Date: Fri, 19 Apr 2024 16:50:08 +0200
Subject: [PATCH] BUG/MEDIUM: peers: Fix state transitions of a peer

The commit 9425aeaffb ("BUG/MAJOR: peers: Update peers section state from a
thread-safe manner") introduced regressions about state transitions of a
peer.

A peer may be in a connected, accepted or released state. Before, changes for
these states were performed synchronously. Since the commit above, changes
are mainly performed in the sync process task.

The first regression was about the released then accepted state transition,
called the renewed state. In reality the state was always crushed by the
accepted state. After some review, the state was just removed to always
perform the cleanup in the sync process task before acknowledging the
connected or accepted states.

Then, a wakeup of the peer applet was missing from the sync process task
after the ack of connected or accepted states, blocking the applet.

Finally, when a peer is in released, connected or accepted state, we must
take care to wait the sync process task wakeup before trying to receive or
send messages.

This patch must only be backported if the above commit is backported.

diff --git a/src/peers.c b/src/peers.c
index 9dda21a55..833106888 100644
--- a/src/peers.c
+++ b/src/peers.c
@@ -100,7 +100,7 @@
 #define PEER_F_LEARN_FINISHED       0x00000800 /* Learn from peer fully finished */
 #define PEER_F_ST_ACCEPTED          0x00001000 /* Used to set a peer in accepted state.  */
 #define PEER_F_ST_CONNECTED         0x00002000 /* Used to set a peer in connected state.  */
-#define PEER_F_ST_RENEWED           0x00004000 /* Used to set a peer in accepted state and old connection was replaced.  */
+/* unused : 0x00004000  */
 #define PEER_F_ST_RELEASED          0x00008000 /* Used to set a peer in released state.  */
 #define PEER_F_RESYNC_REQUESTED     0x00010000 /* A resnyc was explicitly requested */
 /* unused : 0x00020000..0x10000000 */
@@ -110,7 +110,7 @@

 #define PEER_TEACH_RESET            ~(PEER_F_TEACH_PROCESS|PEER_F_TEACH_FINISHED) /* PEER_F_TEACH_COMPLETE should never be reset */
 #define PEER_LEARN_RESET            ~(PEER_F_LEARN_ASSIGN|PEER_F_LEARN_PROCESS|PEER_F_LEARN_FINISHED|PEER_F_LEARN_NOTUP2DATE)
-#define PEER_STATE_RESET            ~(PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED|PEER_F_ST_RENEWED|PEER_F_ST_RELEASED)
+#define PEER_STATE_RESET            ~(PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED|PEER_F_ST_RELEASED)


 #define PEER_RESYNC_TIMEOUT         5000 /* 5 seconds */
@@ -3013,10 +3013,6 @@ static void peer_io_handler(struct appctx *appctx)
 					curpeer->reconnect = tick_add(now_ms, MS_TO_TICKS(50 + ha_random() % 2000));
 					peer_session_forceshutdown(curpeer);

-					/* old peer connection was replaced by a new one. */
-					curpeer->flags &= PEER_STATE_RESET;
-					curpeer->flags |= PEER_F_ST_RENEWED;
-
 					curpeer->heartbeat = TICK_ETERNITY;
 					curpeer->coll++;
 				}
@@ -3142,6 +3138,9 @@ static void peer_io_handler(struct appctx *appctx)
 					}
 				}

+				if (curpeer->flags & (PEER_F_ST_RELEASED|PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED))
+					goto out;
+
 				reql = peer_recv_msg(appctx, (char *)msg_head, sizeof msg_head, &msg_len, &totl);
 				if (reql <= 0) {
 					if (reql == -1)
@@ -3384,7 +3383,7 @@ static void __process_peer_state(struct peers *peers, struct peer *peer)
 		peers->flags |= PEERS_F_RESYNC_REQUESTED;

 	/* Check peer state. Order is important */
-	if (peer->flags & (PEER_F_ST_RELEASED|PEER_F_ST_RENEWED)) {
+	if (peer->flags & (PEER_F_ST_RELEASED|PEER_F_ST_CONNECTED|PEER_F_ST_ACCEPTED)) {
 		if (peer->flags & PEER_F_LEARN_ASSIGN) {
 			/* unassign current peer for learning */
 			peers->flags &= ~(PEERS_F_RESYNC_ASSIGN|PEERS_F_RESYNC_PROCESS);
@@ -3395,7 +3394,7 @@ static void __process_peer_state(struct peers *peers, struct peer *peer)
 		peer->flags &= PEER_TEACH_RESET;
 		peer->flags &= PEER_LEARN_RESET;
 	}
-	if (peer->flags & (PEER_F_ST_ACCEPTED|PEER_F_ST_RENEWED)) {
+	if (peer->flags & PEER_F_ST_ACCEPTED) {
 		peer->flags &= PEER_TEACH_RESET;
 		peer->flags &= PEER_LEARN_RESET;

@@ -3438,6 +3437,9 @@ static void __process_peer_state(struct peers *peers, struct peer *peer)
 			peers->flags |= PEERS_F_RESYNC_REMOTEASSIGN;
 		}
 	}
+
+	if (peer->flags & (PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED))
+		appctx_wakeup(peer->appctx);
 	peer->flags &= PEER_STATE_RESET;
 }

-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
BUG/MEDIUM: peers: Fix state transitions of a peer

The commit 9425aeaffb ("BUG/MAJOR: peers: Update peers section state from a
thread-safe manner") introduced regressions about state transitions of a
peer.

A peer may be in a connected, accepted or released state. Before, changes for
these states were performed synchronously. Since the commit above, changes
are mainly performed in the sync process task.

The first regression was about the released then accepted state transition,
called the renewed state. In reality the state was always crushed by the
accepted state. After some review, the state was just removed to always
perform the cleanup in the sync process task before acknowledging the
connected or accepted states.

Then, a wakeup of the peer applet was missing from the sync process task
after the ack of connected or accepted states, blocking the applet.

Finally, when a peer is in released, connected or accepted state, we must
take care to wait the sync process task wakeup before trying to receive or
send messages.

This patch must only be backported if the above commit is backported.

Here is the root cause:
The bug was caused by the introduction of asynchronous state transitions for peers, which led to improper handling of the `RENEWED` state. Specifically, the state transitions were not correctly managed, resulting in the `RENEWED` state being overridden by the `ACCEPTED` state without proper cleanup, and a missing wakeup call for the peer applet, which blocked message processing. This created inconsistencies in the peer's state management during synchronization tasks.

Here is the patch:
 #define PEER_F_ST_ACCEPTED          0x00001000 /* Used to set a peer in accepted state.  */
 #define PEER_F_ST_CONNECTED         0x00002000 /* Used to set a peer in connected state.  */
-#define PEER_F_ST_RENEWED           0x00004000 /* Used to set a peer in accepted state and old connection was replaced.  */
+/* unused : 0x00004000  */
 #define PEER_F_ST_RELEASED          0x00008000 /* Used to set a peer in released state.  */
 #define PEER_F_RESYNC_REQUESTED     0x00010000 /* A resnyc was explicitly requested */
 #define PEER_TEACH_RESET            ~(PEER_F_TEACH_PROCESS|PEER_F_TEACH_FINISHED) /* PEER_F_TEACH_COMPLETE should never be reset */
 #define PEER_LEARN_RESET            ~(PEER_F_LEARN_ASSIGN|PEER_F_LEARN_PROCESS|PEER_F_LEARN_FINISHED|PEER_F_LEARN_NOTUP2DATE)
-#define PEER_STATE_RESET            ~(PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED|PEER_F_ST_RENEWED|PEER_F_ST_RELEASED)
+#define PEER_STATE_RESET            ~(PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED|PEER_F_ST_RELEASED)


  */
 static void peer_io_handler(struct appctx *appctx)
 {
 	struct stconn *sc = appctx_sc(appctx);
 	struct stream *s = __sc_strm(sc);
 	struct peers *curpeers = strm_fe(s)->parent;
 	struct peer *curpeer = NULL;
 	int reql = 0;
 	int repl = 0;
 	unsigned int maj_ver, min_ver;
 	int prev_state;

 	if (unlikely(se_fl_test(appctx->sedesc, (SE_FL_EOS|SE_FL_ERROR)))) {
 		co_skip(sc_oc(sc), co_data(sc_oc(sc)));
 		goto out;
 	}

 	/* Check if the input buffer is available. */
 	if (sc_ib(sc)->size == 0) {
 		sc_need_room(sc, 0);
 		goto out;
 	}

 	while (1) {
 		prev_state = appctx->st0;
 switchstate:
 		maj_ver = min_ver = (unsigned int)-1;
 		switch(appctx->st0) {
 			case PEER_SESS_ST_ACCEPT:
 				prev_state = appctx->st0;
 				appctx->svcctx = NULL;
 				appctx->st0 = PEER_SESS_ST_GETVERSION;
 				__fallthrough;
 			case PEER_SESS_ST_GETVERSION:
 				prev_state = appctx->st0;
 				reql = peer_getline_version(appctx, &maj_ver, &min_ver);
 				if (reql <= 0) {
 					if (!reql)
 						goto out;
 					goto switchstate;
 				}

 				appctx->st0 = PEER_SESS_ST_GETHOST;
 				__fallthrough;
 			case PEER_SESS_ST_GETHOST:
 				prev_state = appctx->st0;
 				reql = peer_getline_host(appctx);
 				if (reql <= 0) {
 					if (!reql)
 						goto out;
 					goto switchstate;
 				}

 				appctx->st0 = PEER_SESS_ST_GETPEER;
 				__fallthrough;
 			case PEER_SESS_ST_GETPEER: {
 				prev_state = appctx->st0;
 				reql = peer_getline_last(appctx, &curpeer);
 				if (reql <= 0) {
 					if (!reql)
 						goto out;
 					goto switchstate;
 				}

 				HA_SPIN_LOCK(PEER_LOCK, &curpeer->lock);
 				if (curpeer->appctx && curpeer->appctx != appctx) {
 					if (curpeer->local) {
 						/* Local connection, reply a retry */
 						appctx->st0 = PEER_SESS_ST_EXIT;
 						appctx->st1 = PEER_SESS_SC_TRYAGAIN;
 						goto switchstate;
 					}

 					/* we're killing a connection, we must apply a random delay before
 					 * retrying otherwise the other end will do the same and we can loop
 					 * for a while.
 					 */
 					curpeer->reconnect = tick_add(now_ms, MS_TO_TICKS(50 + ha_random() % 2000));
 					peer_session_forceshutdown(curpeer);

-					/* old peer connection was replaced by a new one. */
-					curpeer->flags &= PEER_STATE_RESET;
-					curpeer->flags |= PEER_F_ST_RENEWED;
-
 					curpeer->heartbeat = TICK_ETERNITY;
 					curpeer->coll++;
 				}
 				if (maj_ver != (unsigned int)-1 && min_ver != (unsigned int)-1) {
 					if (min_ver == PEER_DWNGRD_MINOR_VER) {
 						curpeer->flags |= PEER_F_DWNGRD;
 					}
 					else {
 						curpeer->flags &= ~PEER_F_DWNGRD;
 					}
 				}
 				curpeer->appctx = appctx;
 				curpeer->flags |= PEER_F_ALIVE;
 				appctx->svcctx = curpeer;
 				appctx->st0 = PEER_SESS_ST_SENDSUCCESS;
 				_HA_ATOMIC_INC(&active_peers);
 			}
 			__fallthrough;
 			case PEER_SESS_ST_SENDSUCCESS: {
 				prev_state = appctx->st0;
 				if (!curpeer) {
 					curpeer = appctx->svcctx;
 					HA_SPIN_LOCK(PEER_LOCK, &curpeer->lock);
 					if (curpeer->appctx != appctx) {
 						appctx->st0 = PEER_SESS_ST_END;
 						goto switchstate;
 					}
 				}

 				repl = peer_send_status_successmsg(appctx);
 				if (repl <= 0) {
 					if (repl == -1)
 						goto out;
 					goto switchstate;
 				}

 				init_accepted_peer(curpeer, curpeers);

 				/* switch to waiting message state */
 				_HA_ATOMIC_INC(&connected_peers);
 				appctx->st0 = PEER_SESS_ST_WAITMSG;
 				goto switchstate;
 			}
 			case PEER_SESS_ST_CONNECT: {
 				prev_state = appctx->st0;
 				if (!curpeer) {
 					curpeer = appctx->svcctx;
 					HA_SPIN_LOCK(PEER_LOCK, &curpeer->lock);
 					if (curpeer->appctx != appctx) {
 						appctx->st0 = PEER_SESS_ST_END;
 						goto switchstate;
 					}
 				}

 				repl = peer_send_hellomsg(appctx, curpeer);
 				if (repl <= 0) {
 					if (repl == -1)
 						goto out;
 					goto switchstate;
 				}

 				/* switch to the waiting statuscode state */
 				appctx->st0 = PEER_SESS_ST_GETSTATUS;
 			}
 			__fallthrough;
 			case PEER_SESS_ST_GETSTATUS: {
 				prev_state = appctx->st0;
 				if (!curpeer) {
 					curpeer = appctx->svcctx;
 					HA_SPIN_LOCK(PEER_LOCK, &curpeer->lock);
 					if (curpeer->appctx != appctx) {
 						appctx->st0 = PEER_SESS_ST_END;
 						goto switchstate;
 					}
 				}

 				if (sc_ic(sc)->flags & CF_WROTE_DATA)
 					curpeer->statuscode = PEER_SESS_SC_CONNECTEDCODE;

 				reql = peer_getline(appctx);
 				if (!reql)
 					goto out;

 				if (reql < 0)
 					goto switchstate;

 				/* Register status code */
 				curpeer->statuscode = atoi(trash.area);
 				curpeer->last_hdshk = now_ms;

 				/* Awake main task */
 				task_wakeup(curpeers->sync_task, TASK_WOKEN_MSG);

 				/* If status code is success */
 				if (curpeer->statuscode == PEER_SESS_SC_SUCCESSCODE) {
 					init_connected_peer(curpeer, curpeers);
 				}
 				else {
 					if (curpeer->statuscode == PEER_SESS_SC_ERRVERSION)
 						curpeer->flags |= PEER_F_DWNGRD;
 					/* Status code is not success, abort */
 					appctx->st0 = PEER_SESS_ST_END;
 					goto switchstate;
 				}
 				_HA_ATOMIC_INC(&connected_peers);
 				appctx->st0 = PEER_SESS_ST_WAITMSG;
 			}
 			__fallthrough;
 			case PEER_SESS_ST_WAITMSG: {
 				uint32_t msg_len = 0;
 				char *msg_cur = trash.area;
 				char *msg_end = trash.area;
 				unsigned char msg_head[7]; // 2 + 5 for varint32
 				int totl = 0;

 				prev_state = appctx->st0;
 				if (!curpeer) {
 					curpeer = appctx->svcctx;
 					HA_SPIN_LOCK(PEER_LOCK, &curpeer->lock);
 					if (curpeer->appctx != appctx) {
 						appctx->st0 = PEER_SESS_ST_END;
 						goto switchstate;
 					}
 				}

+				if (curpeer->flags & (PEER_F_ST_RELEASED|PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED))
+					goto out;
+
 				reql = peer_recv_msg(appctx, (char *)msg_head, sizeof msg_head, &msg_len, &totl);
 				if (reql <= 0) {
 					if (reql == -1)
 						goto switchstate;
 					goto send_msgs;
 				}

 				msg_end += msg_len;
 				if (!peer_treat_awaited_msg(appctx, curpeer, msg_head, &msg_cur, msg_end, msg_len, totl))
 					goto switchstate;

 				curpeer->flags |= PEER_F_ALIVE;

 				/* skip consumed message */
 				co_skip(sc_oc(sc), totl);
 				/* loop on that state to peek next message */
 				goto switchstate;

 send_msgs:
 				if (curpeer->flags & PEER_F_HEARTBEAT) {
 					curpeer->flags &= ~PEER_F_HEARTBEAT;
 					repl = peer_send_heartbeatmsg(appctx, curpeer, curpeers);
 					if (repl <= 0) {
 						if (repl == -1)
 							goto out;
 						goto switchstate;
 					}
 					curpeer->tx_hbt++;
 				}
 				/* we get here when a peer_recv_msg() returns 0 in reql */
 				repl = peer_send_msgs(appctx, curpeer, curpeers);
 				if (repl <= 0) {
 					if (repl == -1)
 						goto out;
 					goto switchstate;
 				}

 				/* noting more to do */
 				goto out;
 			}
 			case PEER_SESS_ST_EXIT:
 				if (prev_state == PEER_SESS_ST_WAITMSG)
 					_HA_ATOMIC_DEC(&connected_peers);
 				prev_state = appctx->st0;
 				if (peer_send_status_errormsg(appctx) == -1)
 					goto out;
 				appctx->st0 = PEER_SESS_ST_END;
 				goto switchstate;
 			case PEER_SESS_ST_ERRSIZE: {
 				if (prev_state == PEER_SESS_ST_WAITMSG)
 					_HA_ATOMIC_DEC(&connected_peers);
 				prev_state = appctx->st0;
 				if (peer_send_error_size_limitmsg(appctx) == -1)
 					goto out;
 				appctx->st0 = PEER_SESS_ST_END;
 				goto switchstate;
 			}
 			case PEER_SESS_ST_ERRPROTO: {
 				TRACE_PROTO("protocol error", PEERS_EV_PROTOERR,
 				            NULL, curpeer, &prev_state);
 				if (curpeer)
 					curpeer->proto_err++;
 				if (prev_state == PEER_SESS_ST_WAITMSG)
 					_HA_ATOMIC_DEC(&connected_peers);
 				prev_state = appctx->st0;
 				if (peer_send_error_protomsg(appctx) == -1) {
 					TRACE_PROTO("could not send error message", PEERS_EV_PROTOERR);
 					goto out;
 				}
 				appctx->st0 = PEER_SESS_ST_END;
 				prev_state = appctx->st0;
 			}
 			__fallthrough;
 			case PEER_SESS_ST_END: {
 				if (prev_state == PEER_SESS_ST_WAITMSG)
 					_HA_ATOMIC_DEC(&connected_peers);
 				prev_state = appctx->st0;
 				if (curpeer) {
 					HA_SPIN_UNLOCK(PEER_LOCK, &curpeer->lock);
 					curpeer = NULL;
 				}
 				se_fl_set(appctx->sedesc, SE_FL_EOS|SE_FL_EOI);
 				co_skip(sc_oc(sc), co_data(sc_oc(sc)));
 				goto out;
 			}
 		}
 	}
 out:
 	sc_opposite(sc)->flags |= SC_FL_RCV_ONCE;

 	if (curpeer)
 		HA_SPIN_UNLOCK(PEER_LOCK, &curpeer->lock);
 	return;
 }


 static void __process_peer_state(struct peers *peers, struct peer *peer)
 {
 	if (peer->flags & PEER_F_RESYNC_REQUESTED)
 		peers->flags |= PEERS_F_RESYNC_REQUESTED;

 	/* Check peer state. Order is important */
-	if (peer->flags & (PEER_F_ST_RELEASED|PEER_F_ST_RENEWED)) {
+	if (peer->flags & (PEER_F_ST_RELEASED|PEER_F_ST_CONNECTED|PEER_F_ST_ACCEPTED)) {
 		if (peer->flags & PEER_F_LEARN_ASSIGN) {
 			/* unassign current peer for learning */
 			peers->flags &= ~(PEERS_F_RESYNC_ASSIGN|PEERS_F_RESYNC_PROCESS);
 			peers->flags |= (peer->local ? PEERS_F_RESYNC_LOCALABORT : PEERS_F_RESYNC_REMOTEABORT);
 			/* reschedule a resync */
 			peers->resync_timeout = tick_add(now_ms, MS_TO_TICKS(5000));
 		}
 		peer->flags &= PEER_TEACH_RESET;
 		peer->flags &= PEER_LEARN_RESET;
 	}
-	if (peer->flags & (PEER_F_ST_ACCEPTED|PEER_F_ST_RENEWED)) {
+	if (peer->flags & PEER_F_ST_ACCEPTED) {
 		peer->flags &= PEER_TEACH_RESET;
 		peer->flags &= PEER_LEARN_RESET;

 		/* if current peer is local */
 		if (peer->local) {
 			/* if current host need resyncfrom local and no process assigned  */
 			if ((peers->flags & PEERS_RESYNC_STATEMASK) == PEERS_RESYNC_FROMLOCAL &&
 			    !(peers->flags & PEERS_F_RESYNC_ASSIGN)) {
 				/* assign local peer for a lesson, consider lesson already requested */
 				peer->flags |= PEER_F_LEARN_ASSIGN;
 				peers->flags |= (PEERS_F_RESYNC_ASSIGN|PEERS_F_RESYNC_PROCESS);
 				peers->flags |= PEERS_F_RESYNC_LOCALASSIGN;
 			}
 		}
 		else if ((peers->flags & PEERS_RESYNC_STATEMASK) == PEERS_RESYNC_FROMREMOTE &&
 			 !(peers->flags & PEERS_F_RESYNC_ASSIGN)) {
 			/* assign peer for a lesson  */
 			peer->flags |= PEER_F_LEARN_ASSIGN;
 			peers->flags |= PEERS_F_RESYNC_ASSIGN;
 			peers->flags |= PEERS_F_RESYNC_REMOTEASSIGN;
 		}
 	}
 	if (peer->flags & PEER_F_ST_CONNECTED) {
 		peer->flags &= PEER_TEACH_RESET;
 		peer->flags &= PEER_LEARN_RESET;

 		/* If current peer is local */
 		if (peer->local) {
 			/* flag to start to teach lesson */
 			peer->flags |= PEER_F_TEACH_PROCESS;
 		}
 		else if ((peers->flags & PEERS_RESYNC_STATEMASK) == PEERS_RESYNC_FROMREMOTE &&
 			 !(peers->flags & PEERS_F_RESYNC_ASSIGN)) {
 			/* If peer is remote and resync from remote is needed,
 			   and no peer currently assigned */

 			/* assign peer for a lesson */
 			peer->flags |= PEER_F_LEARN_ASSIGN;
 			peers->flags |= PEERS_F_RESYNC_ASSIGN;
 			peers->flags |= PEERS_F_RESYNC_REMOTEASSIGN;
 		}
 	}
+
+	if (peer->flags & (PEER_F_ST_ACCEPTED|PEER_F_ST_CONNECTED))
+		appctx_wakeup(peer->appctx);
 	peer->flags &= PEER_STATE_RESET;
 }



